  const stdout=execFileSync(process.execPath,[path.join(root,"scripts","scaffold-library-module.mjs"),"https://library.vcvrack.com/FixturePlugin/Modern","--manifest-file",path.join(source,"plugin.json"),"--source-dir",source,"--output",output,"--compile"],{encoding:"utf8"}),report=JSON.parse(stdout),runtime=JSON.parse(fs.readFileSync(path.join(output,"runtime.json"),"utf8"));
  assert.equal(report.assessment.compileEligible,true);assert.equal(report.detected.panelWidth,75);assert.deepEqual(report.detected.features,["custom-state","expanders","simd","rack-dsp","json","bypass-routes"]);assert.deepEqual(report.detected.inheritance.secondaryBases,["FixtureMeterInterface"]);assert.equal(runtime.width,75);assert.deepEqual(runtime.params,[{id:0,name:"Rate",min:Math.fround(Math.log2(1e-3)),max:3,default:-3}]);assert.equal(runtime.inputs.length,1);assert.equal(runtime.outputs.length,8);assert.equal(runtime.runtime.expanderMode,"message-buffer");assert.deepEqual(runtime.runtime.expander.models,[{key:"FixturePlugin/ExpanderOnly",symbol:"modelExpanderOnly",index:0}]);assert.equal(runtime.runtime.initialMemory,4194304);assert.deepEqual(runtime.bypassRoutes,[[0,0]]);assert.deepEqual(runtime.stateKeys,[{key:"multiplier",type:"integer"},{key:"enabled",type:"boolean"},{key:"offsets",type:"real",index:0},{key:"offsets",type:"real",index:1},{key:"offsets",type:"real",index:2},{key:"matrix",type:"real",path:[0,0]},{key:"matrix",type:"real",path:[0,1]},{key:"matrix",type:"real",path:[1,0]},{key:"matrix",type:"real",path:[1,1]}]);const adapter=fs.readFileSync(path.join(output,"adapter.cpp"),"utf8");assert.match(adapter,/struct ModernModule : Module, FixtureMeterInterface/);assert.match(adapter,/ModernModule\(\)\s*\{/);assert.match(adapter,/configParam<EditableQuantity>\(RATE_PARAM/);assert.match(adapter,/const int configSwitch = 1/);assert.match(adapter,/rightExpander\.module/);assert.doesNotMatch(adapter,/nativeMeter\{/);
  const wasm=new WebAssembly.Instance(new WebAssembly.Module(fs.readFileSync(path.join(output,"module.wasm"))),{}).exports;wasm._initialize();assert.equal(wasm.rack_web_output_count(),8);assert.equal(wasm.rack_web_light_count(),1);wasm.rack_web_set_input_connected(0,1);wasm.rack_web_set_input_channels(0,1);wasm.rack_web_set_state(0,2);wasm.rack_web_set_state(2,1.25);wasm.rack_web_set_state(8,0.75);new Float32Array(wasm.memory.buffer,wasm.rack_web_input_buffer(),128)[0]=2.5;wasm.rack_web_process(1,48000);const values=new Float32Array(wasm.memory.buffer,wasm.rack_web_output_buffer(),8*16*128);for(let port=0;port<8;port++)assert.equal(values[port*128],7);assert.equal(new Float32Array(wasm.memory.buffer,wasm.rack_web_light_buffer(),1)[0],0);
