  const gitEnvironment={...process.env,GIT_AUTHOR_NAME:"Rack Web",GIT_AUTHOR_EMAIL:"rack-web@example.invalid",GIT_COMMITTER_NAME:"Rack Web",GIT_COMMITTER_EMAIL:"rack-web@example.invalid"},git=(directory,...parameters)=>execFileSync("git",["-C",directory,...parameters],{env:gitEnvironment,stdio:"ignore"});execFileSync("git",["init",dependency],{env:gitEnvironment,stdio:"ignore"});git(dependency,"add",".");git(dependency,"commit","-m","fixture dependency");execFileSync("git",["init",plugin],{env:gitEnvironment,stdio:"ignore"});git(plugin,"add",".");git(plugin,"commit","-m","fixture plugin");
  execFileSync(process.execPath,[path.join(root,"scripts","scaffold-library-module.mjs"),"https://library.vcvrack.com/FixturePlugin/Simple","--manifest-file",path.join(plugin,"plugin.json"),"--source-dir",plugin,"--output",output,"--compile"],{encoding:"utf8"});
